// chained and covered by a checkpoint (up to sealed_seq).
func (q *Queries) RetentionSealedSeq(ctx context.Context, orgID ids.OrgID) (int64, error) {
	row := q.db.QueryRow(ctx, retentionSealedSeq, orgID)
	var seq int64
	err := row.Scan(&seq)
	return seq, err
}
